from __future__ import annotations

import pip._vendor.urllib3.connection as urllib3_connection

from ...connectionpool import HTTPConnectionPool, HTTPSConnectionPool
from .connection import EmscriptenHTTPConnection, EmscriptenHTTPSConnection

def inject_into_urllib3() -> None:
    HTTPConnectionPool.ConnectionCls = EmscriptenHTTPConnection
    HTTPSConnectionPool.ConnectionCls = EmscriptenHTTPSConnection
    urllib3_connection.HTTPConnection = EmscriptenHTTPConnection
    urllib3_connection.HTTPSConnection = EmscriptenHTTPSConnection
    urllib3_connection.VerifiedHTTPSConnection = EmscriptenHTTPSConnection
